-- Controlled existing-authority fixtures, not the physics implementation or M2 data.
CREATE ROLE anon LOGIN; CREATE ROLE authenticated LOGIN; CREATE ROLE service_role LOGIN;
CREATE SCHEMA auth; CREATE SCHEMA extensions; CREATE EXTENSION pgcrypto WITH SCHEMA extensions;
CREATE FUNCTION auth.role() RETURNS text LANGUAGE sql AS $$ SELECT current_setting('fixture.jwt_role',true) $$;
CREATE TABLE public.gto_v31_datasets(dataset_id uuid PRIMARY KEY,state text,policy_representation text,input_bundle_id uuid,input_bundle_checksum text,declared_coverage jsonb);
CREATE TABLE public.gto_v31_input_bundles(input_bundle_id uuid,approval_status text,bundle_checksum text);
CREATE TABLE public.gto_v31_runtime_cells(dataset_id uuid,cell_key_checksum text,policy_representation text,model_checksum text,model_build_receipt_checksum text,template_checksum text,training_provenance_checksum text,public_template jsonb,public_training_provenance jsonb,public_model_build_receipt jsonb);
CREATE TABLE public.gto_v31_public_selections(dataset_id uuid,input_bundle_checksum text,receipt_checksum text,receipt jsonb,capture_checksum text,selected jsonb,frozen_models jsonb);
CREATE TABLE public.gto_v31_public_source_journal(dataset_id uuid,source_row_id uuid,source_node text,context jsonb,board text,node_checksum text,artifact_checksum text,machine_id text);
CREATE TABLE public.gto_v31_model_preparations(dataset_id uuid,cell_key_checksum text,context jsonb,identity jsonb);
CREATE TABLE public.gto_v31_model_freezes(dataset_id uuid,cell_key_checksum text,public_model_build_receipt jsonb,model_build_receipt_checksum text);
CREATE TABLE public.fixture_gates(selection boolean,headers boolean,frozen boolean,map boolean,audit text,quarantine_on_audit boolean DEFAULT false);
INSERT INTO public.fixture_gates VALUES(true,true,true,true,repeat('9',64),false);
CREATE TABLE public.fixture_audit_calls(dataset_id uuid,cell_key text,board text[]);
CREATE FUNCTION public.fn_gto_v31_public215_selected_complete(d public.gto_v31_datasets) RETURNS boolean LANGUAGE sql AS $$SELECT selection FROM public.fixture_gates$$;
CREATE FUNCTION public.fn_gto_v31_public215_source_headers_valid(d public.gto_v31_datasets) RETURNS boolean LANGUAGE sql AS $$SELECT headers FROM public.fixture_gates$$;
CREATE FUNCTION public.fn_gto_v31_public215_frozen_model_valid(c public.gto_v31_runtime_cells,d public.gto_v31_datasets) RETURNS boolean LANGUAGE sql AS $$SELECT frozen FROM public.fixture_gates$$;
CREATE FUNCTION public.fn_gto_v31_public215_frozen_map(d public.gto_v31_datasets) RETURNS jsonb LANGUAGE plpgsql AS $$BEGIN IF (SELECT map FROM public.fixture_gates) IS NOT TRUE THEN RAISE EXCEPTION 'fixture frozen authority absent';END IF;RETURN '[]'::jsonb;END$$;
CREATE FUNCTION public.fn_gto_v31_public215_digest(j jsonb) RETURNS text LANGUAGE sql AS $$SELECT encode(extensions.digest(j::text,'sha256'),'hex')$$;
CREATE FUNCTION public.fn_gto_v31_public215_rank_signature(board text) RETURNS text LANGUAGE sql AS $$SELECT board$$;
CREATE FUNCTION public.fn_gto_v31_public215_cards(board text) RETURNS boolean LANGUAGE sql AS $$SELECT board~'^(?:[2-9TJQKA][cdhs]){3,5}$'$$;
CREATE FUNCTION public.fn_gto_v31_prepare_public_physics(d uuid,k text,b text[]) RETURNS text LANGUAGE plpgsql AS $$BEGIN INSERT INTO public.fixture_audit_calls VALUES(d,k,b);IF (SELECT quarantine_on_audit FROM public.fixture_gates) THEN UPDATE public.fixture_gates SET headers=false;END IF;RETURN (SELECT audit FROM public.fixture_gates);END$$;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM PUBLIC,anon,authenticated,service_role;
GRANT USAGE ON SCHEMA public TO anon,authenticated,service_role;
INSERT INTO public.gto_v31_datasets VALUES('11111111-1111-4111-8111-111111111111','building','public_hist215_v1','22222222-2222-4222-8222-222222222222',repeat('1',64),(SELECT jsonb_agg(i) FROM generate_series(1,107)i));
INSERT INTO public.gto_v31_input_bundles VALUES('22222222-2222-4222-8222-222222222222','approved',repeat('1',64));
INSERT INTO public.gto_v31_runtime_cells VALUES('11111111-1111-4111-8111-111111111111',repeat('2',64),'public_hist215_v1',repeat('3',64),repeat('4',64),repeat('5',64),repeat('6',64),'{"context":{"street":"flop","role":"fixture"}}',jsonb_build_object('capture_receipt_checksum',repeat('7',64)),'{"format":"fixture-only"}');
INSERT INTO public.gto_v31_model_preparations SELECT dataset_id,cell_key_checksum,public_template->'context',jsonb_build_object('model_checksum',model_checksum,'template_checksum',template_checksum,'training_provenance_checksum',training_provenance_checksum) FROM public.gto_v31_runtime_cells;
INSERT INTO public.gto_v31_model_freezes SELECT dataset_id,cell_key_checksum,public_model_build_receipt,model_build_receipt_checksum FROM public.gto_v31_runtime_cells;
INSERT INTO public.gto_v31_public_source_journal SELECT c.dataset_id,'33333333-3333-4333-8333-333333333333','node-'||i,c.public_template->'context',b,repeat('a',64),repeat('b',64),'M2' FROM public.gto_v31_runtime_cells c CROSS JOIN unnest(ARRAY['KsQd7c','AcKd2h','QcJh3d','Tc9d4s','8c7d5h','6c5d2s','4c3d2h','JcTd8s'])WITH ORDINALITY t(b,i);
INSERT INTO public.gto_v31_public_selections SELECT c.dataset_id,repeat('1',64),repeat('8',64),jsonb_build_object('capture_receipt_checksum',repeat('7',64)),repeat('7',64),(SELECT jsonb_agg(x) FROM (SELECT jsonb_build_object('context_id',public.fn_gto_v31_public215_digest(context),'rank_signature',board,'board',board)x FROM public.gto_v31_public_source_journal UNION ALL SELECT jsonb_build_object('context_id','other-'||i,'rank_signature','other','board','other') FROM generate_series(1,848)i)q),'[]' FROM public.gto_v31_runtime_cells c;
